def cube_root_if_perfect(n):
    if n == 0:
        return 0

    x = n
    while True:
        y = (2 * x + n // (x * x)) // 3
        if y >= x:
            break
        x = y

    if x * x * x == n:
        return x
    elif (x + 1) * (x + 1) * (x + 1) == n:
        return x + 1
    else:
        return None



